import type { TableName } from '../db'

/** Category classifying what aspect of the instance this check evaluates */
type ScanCategory = 'upgradability' | 'performance' | 'security' | 'manageability' | 'user_experience'

/** Priority level: 1=Critical, 2=High, 3=Moderate, 4=Low */
type ScanPriority = '1' | '2' | '3' | '4'

/** Type of column content to scan */
type ColumnType = 'script' | 'xml' | 'html'

/**
 * Base properties shared by all instance scan check types
 */
type ScanCheckBase = {
    /** Unique name identifying this check */
    name: string
    /** Controls whether this check runs during scans. Defaults to true */
    active?: boolean
    /** Classifies what aspect of the instance this check evaluates */
    category: ScanCategory
    /** Severity level: 1=Critical, 2=High, 3=Moderate, 4=Low */
    priority: ScanPriority
    /** Brief summary displayed in scan results */
    shortDescription: string
    /** Server-side script executed when the check runs */
    script?: string
    /** Full explanation of what this check evaluates and why */
    description?: string
    /** Guidance on how to remediate findings from this check */
    resolutionDetails?: string
    /** Link to external documentation for this check */
    documentationUrl?: string
    /** Minimum number of findings before scoring applies */
    scoreMin?: number
    /** Maximum number of findings for scoring calculation */
    scoreMax?: number
    /** Multiplier applied to the finding count for scoring */
    scoreScale?: number
    /** Encoded query condition that must be met before this check runs */
    runCondition?: string
    /** Table where findings are stored. Defaults to scan_finding */
    findingType?: TableName
}

/**
 * Scans columns of a specific content type (script, XML, or HTML) across the instance (`scan_column_type_check`).
 * @interface
 */
export type ColumnTypeCheck = Now.Internal.WithIdAndMetadata<
    ScanCheckBase & {
        /** Content type of columns to scan */
        columnType: ColumnType
    }
>

/**
 * Runs linting rules against instance code (`scan_linter_check`).
 * @interface
 */
export type LinterCheck = Now.Internal.WithIdAndMetadata<ScanCheckBase>

/**
 * Executes a standalone script-based check with no table binding (`scan_script_only_check`).
 * @interface
 */
export type ScriptOnlyCheck = Now.Internal.WithIdAndMetadata<ScanCheckBase>

/**
 * Scans records in a specific table, optionally using an advanced script (`scan_table_check`).
 *
 * Supports three modes:
 * - Condition-only: use `conditions` to filter records (default)
 * - Script-only: set `advanced: true` and provide a `script`
 * - Combined: set `advanced: true` with both `conditions` and `script`
 * @interface
 */
export type TableCheck<T extends TableName = TableName> = Now.Internal.WithIdAndMetadata<
    ScanCheckBase & {
        /** Table to scan */
        table: T
        /** Enables custom script mode instead of condition-based scanning */
        advanced?: boolean
        /** Encoded query filtering which records to evaluate */
        conditions?: string
        /** Uses the upgrade manifest to scope findings to changed records */
        useManifest?: boolean
    }
>

/**
 * Creates a column type check that scans columns of a specific content type (`scan_column_type_check`).
 *
 * @example
 * ```typescript
 * ColumnTypeCheck({
 *     $id: Now.ID['check-script-columns'],
 *     name: 'Script Column Validator',
 *     active: true,
 *     category: 'security',
 *     priority: '2',
 *     shortDescription: 'Validates script columns for common security issues',
 *     columnType: 'script',
 * })
 * ```
 * @group InstanceScan
 */
export function ColumnTypeCheck(config: ColumnTypeCheck) {
    return config
}

/**
 * Creates a linter check that runs linting rules against instance code (`scan_linter_check`).
 *
 * @example
 * ```typescript
 * LinterCheck({
 *     $id: Now.ID['lint-gs-print'],
 *     name: 'Detect gs.print Usage',
 *     active: true,
 *     category: 'upgradability',
 *     priority: '3',
 *     shortDescription: 'Flags usage of gs.print which is deprecated',
 * })
 * ```
 * @group InstanceScan
 */
export function LinterCheck(config: LinterCheck) {
    return config
}

/**
 * Creates a script-only check that executes a standalone script with no table binding (`scan_script_only_check`).
 *
 * @example
 * ```typescript
 * ScriptOnlyCheck({
 *     $id: Now.ID['check-admin-overuse'],
 *     name: 'Admin Role Overuse',
 *     active: true,
 *     category: 'security',
 *     priority: '1',
 *     shortDescription: 'Detects excessive admin role assignments',
 *     script: Now.include('./check-admin-overuse.js'),
 * })
 * ```
 * @group InstanceScan
 */
export function ScriptOnlyCheck(config: ScriptOnlyCheck) {
    return config
}

/**
 * Creates a table check that scans records in a specific table (`scan_table_check`).
 *
 * Supports three modes:
 * - Condition-only: use `conditions` to filter records (default)
 * - Script-only: set `advanced: true` and provide a `script`
 * - Combined: set `advanced: true` with both `conditions` and `script`
 *
 * @example
 * ```typescript
 * // Condition-based check
 * TableCheck({
 *     $id: Now.ID['check-inactive-users'],
 *     name: 'Inactive Users with Roles',
 *     active: true,
 *     category: 'security',
 *     priority: '2',
 *     shortDescription: 'Finds inactive users that still have active roles',
 *     table: 'sys_user',
 *     conditions: 'active=false^roles!=',
 * })
 *
 * // Advanced script-based check
 * TableCheck({
 *     $id: Now.ID['check-large-attachments'],
 *     name: 'Large Attachment Detector',
 *     active: true,
 *     category: 'performance',
 *     priority: '3',
 *     shortDescription: 'Identifies records with oversized attachments',
 *     table: 'sys_attachment',
 *     advanced: true,
 *     script: Now.include('./check-large-attachments.js'),
 * })
 *
 * // Combined conditions and script check
 * TableCheck({
 *     $id: Now.ID['check-stale-incidents'],
 *     name: 'Stale Incident Detector',
 *     active: true,
 *     category: 'manageability',
 *     priority: '2',
 *     shortDescription: 'Finds incidents that are open and stale',
 *     table: 'incident',
 *     advanced: true,
 *     conditions: 'state!=6^state!=7',
 *     script: Now.include('./check-stale-incidents.js'),
 * })
 * ```
 * @group InstanceScan
 */
export function TableCheck<const T extends TableName>(config: TableCheck<T>) {
    return config
}
